class Solution {
  public long getSum(int[] nums) {
    int n = nums.length;
    long[] pre = new long[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + nums[i];
    int[] d1 = new int[n], d2 = new int[n];
    for (int i = 0, l = 0, r = -1; i < n; i++) {
      int k = i > r ? 1 : Math.min(d1[l + r - i], r - i + 1);
      while (i - k >= 0 && i + k < n && nums[i - k] == nums[i + k]) k++;
      d1[i] = k--;
      if (i + k > r) {
        l = i - k;
        r = i + k;
      }
    }
    for (int i = 0, l = 0, r = -1; i < n; i++) {
      int k = i > r ? 0 : Math.min(d2[l + r - i + 1], r - i + 1);
      while (i - k - 1 >= 0 && i + k < n && nums[i - k - 1] == nums[i + k]) k++;
      d2[i] = k--;
      if (i + k > r) {
        l = i - k - 1;
        r = i + k;
      }
    }
    long best = 0;
    for (int i = 0; i < n; i++) {
      best = Math.max(best, pre[i + d1[i]] - pre[i - d1[i] + 1]);
      if (d2[i] > 0) best = Math.max(best, pre[i + d2[i]] - pre[i - d2[i]]);
    }
    return best;
  }
}
